DROP TABLE IF EXISTS `procedure_instruction`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `procedure_instruction` (
  `pk` int(11) NOT NULL AUTO_INCREMENT,
  `section_name` varchar(100) DEFAULT NULL,
  `text` varchar(10000) DEFAULT NULL,
  `display_order` double DEFAULT NULL,
  `procedure_details_pk` int(11) NOT NULL,
  `edit_type` varchar(15) NOT NULL DEFAULT 'ORIGINAL',
  PRIMARY KEY (`pk`),
  KEY `fk_procedureInstruction_procedureDefVersion_idx` (`procedure_details_pk`),
  CONSTRAINT `fk_procedureInstruction_procedureDetails` FOREIGN KEY (`procedure_details_pk`) REFERENCES `procedure_details` (`pk`)
) ENGINE=InnoDB AUTO_INCREMENT=492 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

