--
-- Table structure for table `step_def`
--

DROP TABLE IF EXISTS `step_def`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `step_def` (
  `pk` int(11) NOT NULL AUTO_INCREMENT,
  `instructions` varchar(5000) DEFAULT NULL,
  `display_order` double DEFAULT NULL,
  `step_group_def_pk` int(11) NOT NULL,
  `step_name` varchar(100) DEFAULT NULL,
  `require_witness` bit(1) DEFAULT NULL,
  `hazardous` bit(1) DEFAULT NULL,
  `mandatory_inspection` bit(1) DEFAULT NULL,
  `type` varchar(255) NOT NULL,
  `edit_type` varchar(15) NOT NULL DEFAULT 'ORIGINAL',
  `run_value_saved_timestamp` timestamp NULL DEFAULT NULL,
  `run_value_entry_user` int(11) DEFAULT NULL,
  `manual_validation` bit(1) NOT NULL DEFAULT b'0',
  `allow_equipment_entry` bit(1) DEFAULT b'0',
  PRIMARY KEY (`pk`),
  KEY `fk_stepDef_stepGroupDef_idx` (`step_group_def_pk`),
  KEY `fk_stepDef_users_idx` (`run_value_entry_user`),
  CONSTRAINT `fk_stepDef_stepGroupDef` FOREIGN KEY (`step_group_def_pk`) REFERENCES `step_group_def` (`pk`),
  CONSTRAINT `fk_stepDef_users` FOREIGN KEY (`run_value_entry_user`) REFERENCES `users` (`user_id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=8389 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

